-- Seed data for ROBOCODE Kit Stock. GENERATED by build_stock_seed.py - do not edit.
-- Re-run the generator after changing kit_data.py or the supplier quote.
-- Costs are landed per kit: components + UK parts + in-house items + 1.50 packaging
-- + sea freight apportioned by weight. USD converted at 0.745178.

on conflict (code) do update set
  name = excluded.name, audience = excluded.audience, sort_order = excluded.sort_order,
  unit_cost = excluded.unit_cost;
-- prices are NOT overwritten on re-run: set them once in the app and they stick.

on conflict (urn) do update set name = excluded.name;

on conflict (name, type) do nothing;
